content:
The navigation wiring is now completely established, and I have built the core **Practice Screen** from scratch to meet the premium aesthetic and functional requirements.

### PHASE 1: Navigation Wiring Fixes

I updated `MainActivity.kt` to decode and pass the `tier` and `format` into the `PracticeScreen` and `PracticeViewModel`. I also updated `PracticeViewModel.kt`'s `startPractice` signature to accept `tier`. 

Here is the exact Kotlin snippet for the updated NavHost section in `MainActivity.kt`:

```kotlin
// In MainActivity.kt NavHost

composable("topics") {
    TopicSelectionScreen(
        topics = topics,
        profile = selectedProfile,
        onTopicSelected = { topicName, tier, format ->
            // Pass all three arguments cleanly in the URI
            navController.navigate("practice/${android.net.Uri.encode(topicName)}/${android.net.Uri.encode(tier)}/${android.net.Uri.encode(format)}")
        },
        onBookmarksClick = { navController.navigate("bookmarks") },
        onAnalyticsClick = { navController.navigate("dashboard") }
    )
}

// ...

composable("practice/{topicName}/{tier}/{format}") { backStackEntry ->
    val topicName = android.net.Uri.decode(backStackEntry.arguments?.getString("topicName") ?: "")
    val tier = android.net.Uri.decode(backStackEntry.arguments?.getString("tier") ?: "")
    val format = android.net.Uri.decode(backStackEntry.arguments?.getString("format") ?: "")

    androidx.compose.runtime.LaunchedEffect(topicName, tier, format, selectedProfile) {
        if (selectedProfile != null) {
            viewModel.startPractice(topicName, selectedProfile!!, tier, format)
        }
    }

    PracticeScreen(
        topicName = topicName,
        tier = tier,
        format = format,
        uiState = uiState,
        onOptionSelected = viewModel::onOptionSelected,
        onBookmarkToggle = viewModel::toggleBookmark,
        onSkip = viewModel::skipQuestion,
        onNext = viewModel::generateNextQuestion,
        onDashboardClick = { navController.navigate("dashboard") }
    )
}
```

### PHASE 2: The Core Practice Screen UI

I have entirely redesigned `PracticeScreen.kt`. It now features:
- **Header Badges**: Cleanly displays the exact Topic, Tier, and Format chosen using `accentGold` and `deepBlue` pills.
- **Interactive Options**: Options are rendered as floating cards. When clicked, it uses `animateColorAsState` to smoothly transition the border and background to Green (Correct) or Red (Incorrect).
- **Inline Trap Dissections**: If the user selects an incorrect answer, a sleek `FeedbackBox` expands instantly directly below the chosen option, rendering the exact "Trap Dissection" (e.g., `TRAP: ABSOLUTE WORDING`).

I physically wrote this to: `c:/Users/harsh/Downloads/tayaari/tayaari files/app/src/main/java/com/example/ui/screens/PracticeScreen.kt`.

Here is the literal, complete Kotlin code for `PracticeScreen.kt`:

```kotlin
package com.example.ui.screens

import androidx.compose.animation.AnimatedContent
import androidx.compose.animation.ExperimentalAnimationApi
import androidx.compose.animation.animateColorAsState
import androidx.compose.animation.core.tween
import androidx.compose.animation.fadeIn
import androidx.compose.animation.fadeOut
import androidx.compose.animation.togetherWith
import androidx.compose.foundation.BorderStroke
import androidx.compose.foundation.background
import androidx.compose.foundation.border
import androidx.compose.foundation.clickable
import androidx.compose.foundation.layout.*
import androidx.compose.foundation.lazy.LazyColumn
import androidx.compose.foundation.shape.CircleShape
import androidx.compose.foundation.shape.RoundedCornerShape
import androidx.compose.material.icons.Icons
import androidx.compose.material.icons.filled.Assessment
import androidx.compose.material.icons.filled.Bookmark
import androidx.compose.material.icons.filled.BookmarkBorder
import androidx.compose.material.icons.filled.WarningAmber
import androidx.compose.material.icons.filled.CheckCircleOutline
import androidx.compose.material.icons.filled.HighlightOff
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.draw.clip
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.unit.dp
import androidx.compose.ui.unit.sp
import com.example.model.ExamQuestion
import com.example.model.MCQQuestion
import com.example.model.DistractorDissection
import com.example.model.Option
import com.example.model.TestMode
import com.example.model.TestUiState

@OptIn(ExperimentalMaterial3Api::class, ExperimentalAnimationApi::class)
@Composable
fun PracticeScreen(
    topicName: String,
    tier: String,
    format: String,
    uiState: TestUiState,
    onOptionSelected: (String) -> Unit,
    onBookmarkToggle: () -> Unit,
    onSkip: () -> Unit,
    onNext: () -> Unit,
    onDashboardClick: () -> Unit
) {
    // Premium color palette
    val surfaceColor = Color(0xFFFDFCF8)
    val deepBlue = Color(0xFF1B3B5A)
    val accentGold = Color(0xFFF4A261)
    val cardColor = Color.White
    val errorRed = Color(0xFFE07A5F)
    val successGreen = Color(0xFF2E7D32)
    val trapBackground = Color(0xFFFFF8F8) // Subtle red tint for trap box

    Scaffold(
        containerColor = surfaceColor,
        topBar = {
            Column {
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(horizontal = 20.dp, vertical = 16.dp),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Column(modifier = Modifier.weight(1f)) {
                        Text(
                            text = topicName.substringAfter(". ").trim(),
                            color = deepBlue,
                            fontWeight = FontWeight.ExtraBold,
                            fontSize = 20.sp,
                            maxLines = 1
                        )
                        Spacer(modifier = Modifier.height(6.dp))
                        Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                            BadgeChip(text = tier.uppercase(), color = accentGold, textColor = Color.White)
                            BadgeChip(text = format, color = deepBlue.copy(alpha = 0.1f), textColor = deepBlue)
                        }
                    }
                    IconButton(onClick = onDashboardClick) {
                        Icon(Icons.Filled.Assessment, contentDescription = "Dashboard", tint = deepBlue)
                    }
                }

                // Progress Bar
                LinearProgressIndicator(
                    progress = if (uiState.totalQuestionsInSet > 0) uiState.questionNumber.toFloat() / uiState.totalQuestionsInSet else 0f,
                    modifier = Modifier.fillMaxWidth().height(4.dp),
                    color = accentGold,
                    trackColor = deepBlue.copy(alpha = 0.1f)
                )
            }
        },
        bottomBar = {
            Surface(
                color = cardColor,
                shadowElevation = 8.dp,
                shape = RoundedCornerShape(topStart = 24.dp, topEnd = 24.dp)
            ) {
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(horizontal = 24.dp, vertical = 16.dp),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    OutlinedButton(
                        onClick = onSkip,
                        enabled = !uiState.isLoading && uiState.selectedOptionId == null,
                        colors = ButtonDefaults.outlinedButtonColors(contentColor = deepBlue),
                        border = BorderStroke(1.dp, deepBlue.copy(alpha = 0.3f)),
                        shape = RoundedCornerShape(12.dp),
                        modifier = Modifier.weight(1f).height(50.dp)
                    ) {
                        Text("Skip", fontWeight = FontWeight.Bold)
                    }
                    Spacer(modifier = Modifier.width(16.dp))
                    Button(
                        onClick = onNext,
                        enabled = uiState.selectedOptionId != null && !uiState.isLoading,
                        colors = ButtonDefaults.buttonColors(containerColor = deepBlue, contentColor = Color.White),
                        shape = RoundedCornerShape(12.dp),
                        modifier = Modifier.weight(1.5f).height(50.dp)
                    ) {
                        Text("Next Question", fontWeight = FontWeight.Bold, fontSize = 16.sp)
                    }
                }
            }
        }
    ) { paddingValues ->
        Box(
            modifier = Modifier
                .fillMaxSize()
                .padding(paddingValues)
        ) {
            val question = uiState.currentQuestion
            if (uiState.isLoading || question == null) {
                Column(
                    modifier = Modifier.fillMaxSize(),
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.Center
                ) {
                    CircularProgressIndicator(color = accentGold)
                    Spacer(modifier = Modifier.height(16.dp))
                    Text("Fetching Next Challenge...", color = deepBlue.copy(alpha = 0.7f), fontWeight = FontWeight.Medium)
                }
            } else {
                AnimatedContent(
                    targetState = question,
                    transitionSpec = {
                        fadeIn(animationSpec = tween(400)).togetherWith(fadeOut(animationSpec = tween(400)))
                    },
                    label = "QuestionAnimation"
                ) { targetQuestion ->
                    LazyColumn(
                        modifier = Modifier.fillMaxSize(),
                        contentPadding = PaddingValues(horizontal = 20.dp, vertical = 24.dp),
                        verticalArrangement = Arrangement.spacedBy(24.dp)
                    ) {
                        item {
                            PremiumQuestionCard(
                                question = targetQuestion,
                                isBookmarked = uiState.isBookmarked,
                                onBookmarkClick = onBookmarkToggle,
                                deepBlue = deepBlue,
                                accentGold = accentGold,
                                cardColor = cardColor
                            )
                        }

                        if (targetQuestion is MCQQuestion) {
                            item {
                                PremiumOptionsList(
                                    options = targetQuestion.options,
                                    selectedOptionId = uiState.selectedOptionId,
                                    correctAnswerId = targetQuestion.correctAnswerId,
                                    correctExplanation = targetQuestion.correctExplanation,
                                    distractorDissections = targetQuestion.distractorDissections,
                                    onOptionSelected = onOptionSelected,
                                    deepBlue = deepBlue,
                                    successGreen = successGreen,
                                    errorRed = errorRed,
                                    cardColor = cardColor,
                                    trapBackground = trapBackground
                                )
                            }
                        }
                    }
                }
            }
        }
    }
}

@Composable
fun BadgeChip(text: String, color: Color, textColor: Color) {
    Box(
        modifier = Modifier
            .background(color, RoundedCornerShape(6.dp))
            .padding(horizontal = 8.dp, vertical = 4.dp)
    ) {
        Text(
            text = text,
            color = textColor,
            fontSize = 11.sp,
            fontWeight = FontWeight.Bold,
            letterSpacing = 0.5.sp
        )
    }
}

@Composable
fun PremiumQuestionCard(
    question: ExamQuestion,
    isBookmarked: Boolean,
    onBookmarkClick: () -> Unit,
    deepBlue: Color,
    accentGold: Color,
    cardColor: Color
) {
    Surface(
        color = cardColor,
        shape = RoundedCornerShape(16.dp),
        shadowElevation = 2.dp,
        modifier = Modifier.fillMaxWidth()
    ) {
        Column(modifier = Modifier.padding(24.dp)) {
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Text(
                    text = "QUESTION",
                    color = accentGold,
                    fontSize = 12.sp,
                    fontWeight = FontWeight.Black,
                    letterSpacing = 1.2.sp
                )
                Icon(
                    imageVector = if (isBookmarked) Icons.Filled.Bookmark else Icons.Filled.BookmarkBorder,
                    contentDescription = "Bookmark",
                    tint = if (isBookmarked) accentGold else deepBlue.copy(alpha = 0.3f),
                    modifier = Modifier.clickable { onBookmarkClick() }.size(28.dp)
                )
            }
            Spacer(modifier = Modifier.height(16.dp))
            Text(
                text = question.questionText.trim(),
                color = deepBlue,
                fontSize = 18.sp,
                fontWeight = FontWeight.SemiBold,
                lineHeight = 26.sp
            )
        }
    }
}

@Composable
fun PremiumOptionsList(
    options: List<Option>,
    selectedOptionId: String?,
    correctAnswerId: String,
    correctExplanation: String,
    distractorDissections: List<DistractorDissection>,
    onOptionSelected: (String) -> Unit,
    deepBlue: Color,
    successGreen: Color,
    errorRed: Color,
    cardColor: Color,
    trapBackground: Color
) {
    val labels = listOf("A", "B", "C", "D")

    Column(verticalArrangement = Arrangement.spacedBy(16.dp)) {
        options.forEachIndexed { index, option ->
            val isSelected = selectedOptionId == option.id
            val isCorrect = option.id == correctAnswerId
            val isAnswerSubmitted = selectedOptionId != null
            val showFeedback = isAnswerSubmitted && isSelected

            val targetBorderColor = when {
                isAnswerSubmitted && isSelected && isCorrect -> successGreen
                isAnswerSubmitted && isSelected && !isCorrect -> errorRed
                isAnswerSubmitted && isCorrect -> successGreen.copy(alpha = 0.5f)
                else -> Color.Transparent
            }

            val targetBgColor = when {
                isAnswerSubmitted && isSelected && isCorrect -> successGreen.copy(alpha = 0.05f)
                isAnswerSubmitted && isSelected && !isCorrect -> errorRed.copy(alpha = 0.05f)
                else -> cardColor
            }

            val animatedBorderColor by animateColorAsState(targetValue = targetBorderColor)
            val animatedBgColor by animateColorAsState(targetValue = targetBgColor)

            Column {
                Surface(
                    color = animatedBgColor,
                    shape = RoundedCornerShape(12.dp),
                    border = BorderStroke(2.dp, animatedBorderColor).takeIf { isAnswerSubmitted && (isSelected || isCorrect) },
                    shadowElevation = if (isAnswerSubmitted) 0.dp else 2.dp,
                    modifier = Modifier
                        .fillMaxWidth()
                        .clickable(enabled = !isAnswerSubmitted) { onOptionSelected(option.id) }
                ) {
                    Row(
                        modifier = Modifier.padding(16.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Box(
                            modifier = Modifier
                                .size(36.dp)
                                .background(deepBlue.copy(alpha = 0.05f), CircleShape)
                                .border(1.dp, deepBlue.copy(alpha = 0.1f), CircleShape),
                            contentAlignment = Alignment.Center
                        ) {
                            Text(
                                text = labels.getOrElse(index) { "" },
                                color = deepBlue,
                                fontWeight = FontWeight.Bold,
                                fontSize = 14.sp
                            )
                        }
                        Spacer(modifier = Modifier.width(16.dp))
                        Text(
                            text = option.text,
                            modifier = Modifier.weight(1f),
                            color = deepBlue.copy(alpha = 0.9f),
                            fontSize = 16.sp,
                            lineHeight = 22.sp
                        )
                        if (isAnswerSubmitted) {
                            if (isSelected && isCorrect) {
                                Icon(Icons.Filled.CheckCircleOutline, tint = successGreen, contentDescription = null)
                            } else if (isSelected && !isCorrect) {
                                Icon(Icons.Filled.HighlightOff, tint = errorRed, contentDescription = null)
                            } else if (isCorrect) {
                                Icon(Icons.Filled.CheckCircleOutline, tint = successGreen.copy(alpha = 0.5f), contentDescription = null)
                            }
                        }
                    }
                }

                // Inline Trap Feedback / Explanation
                if (showFeedback) {
                    Spacer(modifier = Modifier.height(12.dp))
                    if (isCorrect) {
                        FeedbackBox(
                            title = "CORRECT",
                            message = correctExplanation,
                            color = successGreen,
                            bgColor = successGreen.copy(alpha = 0.05f)
                        )
                    } else {
                        val dissection = distractorDissections.find { it.optionId == option.id }
                        FeedbackBox(
                            title = "TRAP: ${dissection?.trapType?.uppercase() ?: "INCORRECT"}",
                            message = dissection?.dissection ?: "That is not the correct answer.",
                            color = errorRed,
                            bgColor = trapBackground
                        )
                    }
                }
            }
        }
    }
}

@Composable
fun FeedbackBox(title: String, message: String, color: Color, bgColor: Color) {
    Surface(
        color = bgColor,
        shape = RoundedCornerShape(12.dp),
        border = BorderStroke(1.dp, color.copy(alpha = 0.3f)),
        modifier = Modifier.fillMaxWidth().padding(start = 24.dp) // Indented slightly
    ) {
        Row(
            modifier = Modifier.padding(16.dp),
            crossAxisAlignment = Alignment.Top
        ) {
            Icon(
                imageVector = Icons.Default.WarningAmber,
                contentDescription = null,
                tint = color,
                modifier = Modifier.size(20.dp).padding(top = 2.dp)
            )
            Spacer(modifier = Modifier.width(12.dp))
            Column {
                Text(
                    text = title,
                    color = color,
                    fontWeight = FontWeight.Black,
                    fontSize = 12.sp,
                    letterSpacing = 1.sp
                )
                Spacer(modifier = Modifier.height(6.dp))
                Text(
                    text = message,
                    color = Color.Black.copy(alpha = 0.8f),
                    fontSize = 14.sp,
                    lineHeight = 20.sp
                )
            }
        }
    }
}
